+
+        List<String> expected = new ArrayList<>(startingLines);
+        expected.add("8.4.1,6305");
+        expected.sort(Comparator.naturalOrder());
+        assertThat(modified.get(), contains(expected.toArray()));
+    }
+
+    @Test
