+        List<String> startingLines = List.of(
+            "8.0.0,6100",
+            "8.0.1,6100",
+            "8.1.0,6204",
+            "8.2.0,6234",
+            "8.3.0,6239",
+            "8.3.1,6260",
+            "8.4.0,6301"
+        );
